		public void Enter_PedestalWindow(global::Dpr.SecretBase.PlacementData placement) {
			StatueEffectData statue = masterData.GetStatueEffectData(placement.data.statueId);
			pedestalWindow.ClearItem();
			pedestalWindow.AddItem(null);
			Pedestal.SheetInfo[] infos = new Pedestal.SheetInfo[pedestals.Info.Length];
			System.Array.Copy(pedestals.Info, infos, pedestals.Info.Length);
			System.Array.Sort(infos, (a, b) => a.sort - b.sort);
			// pedestals that fit the statue's footprint first, then the other owned ones (shown disabled)
			for (int i = 0; i < infos.Length; i++)
			{
				Pedestal.SheetInfo info = infos[i];
				if (pedestalsNum.ContainsKey(info.pedestalId) && info.Width == statue.width && info.Height == statue.height)
				{
					if (pedestalsNum[info.pedestalId] > 0)
						pedestalWindow.AddItem(info);
				}
			}
			for (int i = 0; i < infos.Length; i++)
			{
				Pedestal.SheetInfo info = infos[i];
				if (pedestalsNum.ContainsKey(info.pedestalId) && (info.Width != statue.width || info.Height != statue.height))
				{
					if (pedestalsNum[info.pedestalId] > 0)
					{
						int index = pedestalWindow.AddItem(info);
						// PedestalIcon.SetDisable (@019c7510, flag 0x4cbc803) inlined @019d86c0..019d8728
						pedestalWindow.GetIcon(index).SetDisable(true);
					}
				}
			}
			if (placement.data.pedestalId >= 0)
			{
				int index = pedestalWindow.GetIndex(placement.data.pedestalId);
				if (index > 0)
					pedestalWindow.SetIndex(index);
			}
			if (placement.pedestal == null)
				pedestalWindow.GetIcon(0).SetDisable(true);
			pedestalWindow.ScrollCalc(0);
			pedestalWindow.gameObject.SetActive(true);
			// StatePedestalWindow.Enter_PedestalWindow (@019d5e70) inlined @019d8818..019d8838
			statePedestalWindow.Enter_PedestalWindow(placement);
			stateMachine.ChangeState(State.PedestalWindow);
		}
